from src.billing.tax import invoice_tax


def test_invoice_tax_on_subtotal():
    lines = [{"quantity": 1, "unit_cents": 5}, {"quantity": 1, "unit_cents": 5}]
    # 10 * 0.25 = 2.5 -> 2 (half-even), not 1 + 1 per line... both 2 here; use 0.3
    assert invoice_tax(lines, 0.3, "US-CA") == 3


def test_invoice_tax_quebec_per_line():
    lines = [{"quantity": 1, "unit_cents": 5}, {"quantity": 1, "unit_cents": 5}]
    # each line 5 * 0.3 = 1.5 -> 2 (half-even), summed = 4
    assert invoice_tax(lines, 0.3, "CA-QC") == 4


def test_invoice_tax_half_even():
    assert invoice_tax([{"quantity": 1, "unit_cents": 25}], 0.1, "US-CA") == 2


def test_invoice_tax_exempt_is_zero():
    assert invoice_tax([{"quantity": 3, "unit_cents": 999}], 0, "US-CA") == 0
